CREATE DATABASE IF NOT EXISTS janani;
USE janani;

CREATE TABLE IF NOT EXISTS users (id INT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, mobile VARCHAR(20), date_of_birth DATE, emergency_contact VARCHAR(120), pregnancy_status ENUM('pregnant','postpartum','trying','not_pregnant') DEFAULT 'not_pregnant', role ENUM('user','admin') DEFAULT 'user', is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pregnancy_details (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL UNIQUE, lmp_date DATE, due_date DATE, doctor_name VARCHAR(150), current_information TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pregnancy_week_content (id INT PRIMARY KEY AUTO_INCREMENT, week_number TINYINT NOT NULL UNIQUE, baby_development TEXT, maternal_changes TEXT, nutrition_guidance TEXT, wellness_guidance TEXT, routine_note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, provider_name VARCHAR(150) NOT NULL, appointment_date DATETIME NOT NULL, notes TEXT, status ENUM('upcoming','completed','cancelled') DEFAULT 'upcoming', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_appointments_user_date (user_id, appointment_date));
CREATE TABLE IF NOT EXISTS vaccination_reminders (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, title VARCHAR(150) NOT NULL, description TEXT, reminder_date DATE NOT NULL, reminder_time TIME, reminder_type VARCHAR(60) DEFAULT 'vaccination', delivery_channel ENUM('in_app','sms') DEFAULT 'in_app', delivery_status ENUM('not_applicable','queued','sent','failed') DEFAULT 'not_applicable', provider_reference VARCHAR(180), status ENUM('pending','completed','cancelled') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_reminders_due (status, reminder_date, delivery_status));
CREATE TABLE IF NOT EXISTS notifications (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, title VARCHAR(150) NOT NULL, message TEXT NOT NULL, is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS health_content (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(180) NOT NULL, category VARCHAR(80) NOT NULL, summary TEXT, body TEXT NOT NULL, source_url VARCHAR(500), verification_status ENUM('unverified','verified') DEFAULT 'unverified', last_verified_at DATE, published BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS government_schemes (id INT PRIMARY KEY AUTO_INCREMENT, scheme_name VARCHAR(180) NOT NULL, description TEXT NOT NULL, eligibility TEXT, benefits TEXT, required_documents TEXT, application_info TEXT, official_url VARCHAR(500), verification_status ENUM('unverified','verified') DEFAULT 'unverified', last_verified_at DATE, is_demo BOOLEAN DEFAULT TRUE, is_published BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS menstrual_cycles (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, cycle_start_date DATE NOT NULL, cycle_length SMALLINT DEFAULT 28, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS chat_messages (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, sender ENUM('user','assistant') NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS faq (id INT PRIMARY KEY AUTO_INCREMENT, question TEXT NOT NULL, answer TEXT NOT NULL, category VARCHAR(80), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS health_logs (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, log_type ENUM('body_change','allergy','general') NOT NULL, body_changes TEXT, allergies TEXT, notes TEXT, recorded_date DATE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_health_logs_user_date (user_id, recorded_date));
CREATE TABLE IF NOT EXISTS facilities (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, facility_type ENUM('hospital','anganwadi') NOT NULL, address VARCHAR(500) NOT NULL, phone VARCHAR(30), latitude DECIMAL(9,6), longitude DECIMAL(9,6), source_url VARCHAR(500), verification_status ENUM('unverified','verified') DEFAULT 'unverified', is_demo BOOLEAN DEFAULT TRUE, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_facilities_type (facility_type), INDEX idx_facilities_coordinates (latitude, longitude));
CREATE TABLE IF NOT EXISTS asha_workers (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, verification_status ENUM('unverified','verified') DEFAULT 'unverified', is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_asha_workers (user_id INT PRIMARY KEY, asha_worker_id INT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (asha_worker_id) REFERENCES asha_workers(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS admin_users (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL UNIQUE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
